def inside_poly_inclusive(r,c,poly):
    sign=None
    for i,(r1,c1) in enumerate(poly):
        r2,c2=poly[(i+1)%len(poly)]
        cross=(r2-r1)*(c-c1)-(c2-c1)*(r-r1)
        if abs(cross)<1e-9:continue
        s=cross>0
        if sign is None:sign=s
        elif sign!=s:return False
    return True
